    [3741]={name="Stomping Boots",sourceType="quest_reward",instructions="Reward from the quest “Elixir of Pain” — pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Elixir of Pain",lore="Oh...the flowers are blooming in Hillsbrad and the air is so fresh and brisk. I can't help but to wallow in the misery of it all. I look out my grimy window and long for the day when our New Plague brings this world the death it deserves."},
    [3748]={name="Feline Mantle",sourceType="boss_drop",instructions="Drops from Wolf Master Nandos in Shadowfang Keep.",zone="Shadowfang Keep",npc="Wolf Master Nandos"},
    [3752]={name="Grunt Vest",sourceType="quest_reward",instructions="Reward from the quest “The Rescue” — pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="The Rescue",lore="Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate."},
    [3754]={name="Shepherd's Gloves",sourceType="quest_reward",instructions="Reward from the quest “Costly Menace” — pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Costly Menace",lore="Ain't nothin' that irks me more than losin' these here beautiful horses."},
    [3755]={name="Fish Gutter",sourceType="quest_reward",instructions="Reward from the quest “Stormwind Ho!”. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Stormwind Ho!",lore="My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga."},
