    [5970]={name="Serpent Gloves",sourceType="boss_drop",instructions="Drops from Lord Serpentis in Wailing Caverns.",zone="Wailing Caverns",npc="Lord Serpentis"},
    [6059]={name="Nomadic Vest",sourceType="quest_reward",instructions="Reward from the quest “The Battleboars”. In Red Cloud Mesa.",zone="Red Cloud Mesa",questName="The Battleboars",lore="The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war."},
    [6070]={name="Wolfskin Bracers",sourceType="quest_reward",instructions="Reward from the quest “Wolves Across the Border” — pick it over the other choices. In Northshire Valley.",zone="Northshire Valley",questName="Wolves Across the Border",lore="I hate those nasty timber wolves! But I sure like eating wolf steaks... Bring me tough wolf meat and I will exchange it for something you'll find useful."},
    [6085]={name="Footman Tunic",sourceType="quest_reward",instructions="Reward from the quest “Wanted:  \"Hogger\"” — pick it over the other choices. In Elwynn Forest.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
    [6095]={name="Wandering Boots",sourceType="quest_reward",instructions="Reward from the quest “Return to Kristoff”. In Stormwind City.",zone="Stormwind City",questName="Return to Kristoff",lore="Now that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay."},
    [6179]={name="Privateer's Cape",sourceType="world_drop",instructions="Drops from Brack (rare spawn) in Eastern Kingdoms.",zone="Eastern Kingdoms",npc="Brack"},
    [6187]={name="Dwarven Defender",sourceType="quest_reward",instructions="Reward from the quest “In Defense of the King's Lands” — pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="In Defense of the King's Lands",lore="our scouts have identified the leader of this recent Trogg incursion. It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug."},
    [6191]={name="Kimbra Boots",sourceType="quest_reward",instructions="Reward from the quest “WANTED: Chok'sul” — pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="WANTED: Chok'sul",lore="By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."},
