    [6269]={name="Pioneer Trousers",sourceType="world_drop",instructions="World drop — drops from 466 creature types around level 6-14. Also found on the auction house."},
    [6282]={name="Sacred Burial Trousers",sourceType="quest_reward",instructions="Reward from the quest “Battle of Hillsbrad” — pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Battle of Hillsbrad",lore="Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize."},
