    [6482]={name="Firewalker Boots",sourceType="quest_reward",instructions="Reward from the quest “Elixir of Pain” — pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Elixir of Pain",lore="Oh...the flowers are blooming in Hillsbrad and the air is so fresh and brisk. I can't help but to wallow in the misery of it all. I look out my grimy window and long for the day when our New Plague brings this world the death it deserves."},
