    [6998]={name="Nimbus Boots",sourceType="quest_reward",instructions="Reward from the quest “Twilight Falls”. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Twilight Falls",lore="Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world."},
    [7002]={name="Arctic Buckler",sourceType="quest_reward",instructions="Reward from the quest “Blackfathom Villainy” — pick it over the other choices. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Blackfathom Villainy",lore="Strength has left me. Your help is needed! Long ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well."},
