    [7738]={name="Evergreen Gloves",sourceType="quest_reward",instructions="Reward from the quest “Tharnariun's Hope” — pick it over the other choices. In Darkshore.",zone="Darkshore",questName="Tharnariun's Hope",lore="The survival of our people and lands comes at unfortunate costs. You have spilled the blood of nature's servants; many sick animals you have felled."},
    [7749]={name="Omega Orb",sourceType="quest_reward",instructions="Reward from the quest “Compendium of the Fallen” — pick it over the other choices. In Scarlet Monastery.",zone="Scarlet Monastery",questName="Compendium of the Fallen",lore="The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?"},
    [7751]={name="Vorrel's Boots",sourceType="quest_reward",instructions="Reward from the quest “Vorrel's Revenge”. In Scarlet Monastery.",zone="Scarlet Monastery",questName="Vorrel's Revenge",lore="Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered. Interrogator Vishas did this to me!"},
