    [11469]={name="Bloodband Bracers",sourceType="quest_reward",instructions="Reward from the quest “The Captain's Chest”. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="The Captain's Chest",lore="I used to sail a ship from here all the way to Ratchet, in Kalimdor. I was a successful captain with a sterling reputation. Until... Those cursed sea giants ruined me!"},
