    [11874]={name="Clouddrift Mantle",sourceType="quest_reward",instructions="Reward from the quest “Ancient Spirit” — pick it over the other choices. In Felwood.",zone="Felwood",questName="Ancient Spirit",lore="Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos... The skull of Gul'dan ensured that none were spared here."},
    [11904]={name="Spirit of Aquementas",sourceType="quest_reward",instructions="Reward from the quest “It's Dangerous to Go Alone” — pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="It's Dangerous to Go Alone",lore="I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero..."},
    [11905]={name="Linken's Boomerang",sourceType="quest_reward",instructions="Reward from the quest “It's Dangerous to Go Alone”. In Un'Goro Crater.",zone="Un'Goro Crater",questName="It's Dangerous to Go Alone",lore="I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero...",proc="Use: Flings a magical boomerang towards target enemy dealing 113 to 187 damage and has a chance to stun or disarm them. (3 Min Cooldown)"},
