    [12082]={name="Wyrmhide Spaulders",sourceType="quest_reward",instructions="Reward from the quest “A Taste of Flame” — pick it over the other choices. In Blackrock Depths.",zone="Blackrock Depths",questName="A Taste of Flame",lore="I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave."},
    [12110]={name="Raincaster Drape",sourceType="quest_reward",instructions="Reward from the quest “The Rise of the Machines” — pick it over the other choices. In Blackrock Depths.",zone="Blackrock Depths",questName="The Rise of the Machines",lore="This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him. He was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs."},
