    [16944]={name="Belt of Ten Storms",sourceType="boss_drop",instructions="Drops from Vaelastrasz the Corrupt in Blackwing Lair.",zone="Blackwing Lair",npc="Vaelastrasz the Corrupt",lore="A red dragon of Alexstrasza's flight, broken by Nefarian's experiments. He asks to be killed before the corruption finishes taking him, and apologises while he fights."},
    [16948]={name="Gauntlets of Ten Storms",sourceType="boss_drop",instructions="Drops from Ebonroc in Blackwing Lair.",zone="Blackwing Lair",npc="Ebonroc",lore="One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."},
