    [21372]={name="Stormcaller's Diadem",sourceType="quest_reward",instructions="Reward from the quest “Stormcaller's Diadem”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Stormcaller's Diadem",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21373]={name="Stormcaller's Footguards",sourceType="quest_reward",instructions="Reward from the quest “Stormcaller's Footguards”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Stormcaller's Footguards",lore="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."},
    [21374]={name="Stormcaller's Hauberk",sourceType="quest_reward",instructions="Reward from the quest “Stormcaller's Hauberk”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Stormcaller's Hauberk",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21375]={name="Stormcaller's Leggings",sourceType="quest_reward",instructions="Reward from the quest “Stormcaller's Leggings”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Stormcaller's Leggings",lore="Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power."},
    [21376]={name="Stormcaller's Pauldrons",sourceType="quest_reward",instructions="Reward from the quest “Stormcaller's Pauldrons”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Stormcaller's Pauldrons",lore="Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!"},
