    [22668]={name="Bracers of Subterfuge",sourceType="quest_reward",instructions="Reward from the quest “Epic Armaments of Battle - Friend of the Dawn” — pick it over the other choices. In Eastern Plaguelands.",zone="Eastern Plaguelands",questName="Epic Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power? I must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge."},
    [22730]={name="Eyestalk Waist Cord",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [22731]={name="Cloak of the Devoured",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [22798]={name="Might of Menethil",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Menethil was the royal line of Lordaeron -- King Terenas, and his son Arthas, who became the Lich King. A warhammer carrying that name, guarded by the lich who served Arthas, is not an accident."},
    [22802]={name="Kingsfall",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [22803]={name="Midnight Haze",sourceType="boss_drop",instructions="Drops from Grobbulus in Naxxramas.",zone="Naxxramas",npc="Grobbulus",lore="A walking vat. The Scourge used him to field-test new strains of the plague on whatever wandered into Naxxramas."},
    [22815]={name="Severance",sourceType="boss_drop",instructions="Drops from Patchwerk in Naxxramas.",zone="Naxxramas",npc="Patchwerk",lore="An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."},
    [22819]={name="Shield of Condemnation",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [22939]={name="Band of Unanswered Prayers",sourceType="boss_drop",instructions="Drops from Anub'Rekhan in Naxxramas.",zone="Naxxramas",npc="Anub'Rekhan",lore="A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."},
    [22942]={name="The Widow's Embrace",sourceType="boss_drop",instructions="Drops from Grand Widow Faerlina in Naxxramas.",zone="Naxxramas",npc="Grand Widow Faerlina",lore="A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."},
    [22954]={name="Kiss of the Spider",sourceType="boss_drop",instructions="Drops from Maexxna in Naxxramas.",zone="Naxxramas",npc="Maexxna",lore="A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs.",proc="Use: Increases your haste rating by 200 for 15 sec. (2 Min Cooldown)"},
